import { Component, OnInit, OnDestroy } from '@angular/core';

@Component({
  selector: 'app-hero',
  templateUrl: './hero.component.html',
  styleUrls: ['./hero.component.css']
})
export class HeroComponent implements OnInit, OnDestroy {
  displayText = '';
  roles = ['Full Stack Java Developer', 'Software Engineer', 'Microservices Architect'];
  currentRoleIndex = 0;
  private typingTimer: any;
  private isDeleting = false;
  private charIndex = 0;

  ngOnInit(): void {
    this.typeText();
  }

  ngOnDestroy(): void {
    clearTimeout(this.typingTimer);
  }

  typeText(): void {
    const currentRole = this.roles[this.currentRoleIndex];
    if (this.isDeleting) {
      this.displayText = currentRole.substring(0, this.charIndex - 1);
      this.charIndex--;
    } else {
      this.displayText = currentRole.substring(0, this.charIndex + 1);
      this.charIndex++;
    }

    let speed = this.isDeleting ? 60 : 100;

    if (!this.isDeleting && this.charIndex === currentRole.length) {
      speed = 2000;
      this.isDeleting = true;
    } else if (this.isDeleting && this.charIndex === 0) {
      this.isDeleting = false;
      this.currentRoleIndex = (this.currentRoleIndex + 1) % this.roles.length;
      speed = 400;
    }

    this.typingTimer = setTimeout(() => this.typeText(), speed);
  }

  scrollTo(href: string): void {
    const el = document.querySelector(href);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  }
}
<section id="hero" class="hero-section">
  <!-- Animated background grid -->
  <div class="grid-bg"></div>
  <!-- Glowing orbs -->
  <div class="orb orb-1"></div>
  <div class="orb orb-2"></div>

  <div class="container hero-content">
    <div class="hero-text">
      <p class="hero-greeting animate-delay-1">
        <span class="mono-bracket">//</span> Hello, World! I'm
      </p>
      <h1 class="hero-name animate-delay-2">Pavan Bakal</h1>
      <div class="hero-role animate-delay-3">
        <span class="role-prefix">const role = "</span>
        <span class="typed-text">{{displayText}}</span>
        <span class="cursor">|</span>
        <span class="role-suffix">";</span>
      </div>
      <p class="hero-description animate-delay-4">
        Results-driven engineer with <strong>3.5 years</strong> of experience building enterprise applications.
        Passionate about clean architecture, microservices, and delivering scalable solutions that make an impact.
      </p>

      <div class="hero-stats animate-delay-5">
        <div class="stat">
          <span class="stat-num">3.5<span class="stat-unit">yr</span></span>
          <span class="stat-label">Experience</span>
        </div>
        <div class="stat-divider"></div>
        <div class="stat">
          <span class="stat-num">13<span class="stat-unit">+</span></span>
          <span class="stat-label">Microservices</span>
        </div>
        <div class="stat-divider"></div>
        <div class="stat">
          <span class="stat-num">25<span class="stat-unit">+</span></span>
          <span class="stat-label">REST APIs</span>
        </div>
        <div class="stat-divider"></div>
        <div class="stat">
          <span class="stat-num">40<span class="stat-unit">%</span></span>
          <span class="stat-label">Bug Reduction</span>
        </div>
      </div>

      <div class="hero-actions animate-delay-6">
        <a href="mailto:pavangbakal@gmail.com" class="btn btn-primary">
